function processData(rows) {
  // Input validation
  if (!Array.isArray(rows) || rows === null || rows === undefined) {
    return [];
  }

  // Initialize an array to hold the transformed data
  const transformedData = [];

  // Process each row
  rows.forEach(row => {
    // Check for missing or null field values
    const studyCount = parseInt(row.study_count, 10);
    const period = row.period;

    if (!isNaN(studyCount) && period) {
      transformedData.push({
        study_count: studyCount,
        period: period
      });
    }
  });

  // Sort the transformed data by period
  transformedData.sort((a, b) => {
    const yearA = parseInt(a.period.split('-')[0], 10);
    const yearB = parseInt(b.period.split('-')[0], 10);
    return yearA - yearB;
  });

  return transformedData;
}

