# id: empirical_studies_count_by_period
SELECT (COUNT(?paper) AS ?study_count) ?period WHERE {
  # Link the paper to its contribution using the P31 predicate
  ?paper orkgp:P31 ?contribution .
  # Declare that the contribution is of type Empirical Research Practice (C27001)
  ?contribution a orkgc:C27001 .
  # Get the publication year of the paper
  ?paper orkgp:P29 ?year .

  # Define the periods for grouping
  BIND(
    IF(?year >= 1993 && ?year <= 1999, "1993-1999"^^xsd:string,
      IF(?year >= 2000 && ?year <= 2009, "2000-2009"^^xsd:string,
        IF(?year >= 2010 && ?year <= 2019, "2010-2019"^^xsd:string,
          IF(?year >= 2020 && ?year <= 2025, "2020-2025"^^xsd:string,
            "Other"^^xsd:string
          )
        )
      )
    ) AS ?period
  ) .

  # Ensure that the study has data collection
  OPTIONAL {
    ?contribution orkgp:P56008 ?data_collection .
    ?data_collection rdfs:label ?dc_label .
    FILTER(?dc_label != "no collection"^^xsd:string) # Exclude studies with no data collection
  }

  # Ensure that the study has data analysis
  OPTIONAL {
    ?contribution orkgp:P15124 ?data_analysis .
    ?data_analysis rdfs:label ?da_label .
    FILTER(?da_label != "no analysis"^^xsd:string) # Exclude studies with no data analysis
  }

  # Filter out studies that do not have both data collection and analysis
  FILTER(BOUND(?data_collection) && BOUND(?data_analysis))

} GROUP BY ?period

