function processData(rows) {
  // Input validation
  if (!Array.isArray(rows) || rows === null || rows === undefined) {
    return [];
  }

  // Initialize a map to count evaluation metrics
  const metricCounts = {};

  // Process each row
  rows.forEach(row => {
    const metric = row.evaluation_metricLabel;
    if (metric) {
      // Increment the count for the metric
      metricCounts[metric] = (metricCounts[metric] || 0) + 1;
    }
  });

  // Convert the metricCounts object to an array
  const metricsArray = Object.entries(metricCounts).map(([metric, count]) => ({
    evaluation_metric: metric,
    count: count
  }));

  // Sort the metrics by count in descending order and take the top 10
  const topMetrics = metricsArray
    .sort((a, b) => b.count - a.count)
    .slice(0, 10);

  // Return the transformed data for visualization
  return topMetrics.map(metric => ({
    evaluation_metric: metric.evaluation_metric,
    count: Number(metric.count) // Ensure count is a number
  }));
}
